import "./style.css";
import catalogData from "./catalog-data.json";
import {parseKV,stringifyKV,get,set} from "./kv.js";
import {GCConnection,CMD,encodeItem,encodeDestroy} from "./gc.js";
import {parseLegacySchema,findCaseKey} from "./schema.js";
import {loadOnlineCatalogue,inventoryArtwork} from "./catalog.js";

const $=s=>document.querySelector(s);
const clone=x=>JSON.parse(JSON.stringify(x));
const S={root:[],config:[],items:[],defaultEquips:[],schemaItems:[],paintKits:[],translations:{},legacySkins:null,onlineCatalogueData:null,onlineCataloguePromise:null,onlineCatalogItems:[],loaded:false,inventoryFile:false,configFile:false,dirtyI:false,dirtyC:false,conn:null,page:"inventory",filter:"all",search:"",catalogFilter:"all",catalogSearch:"",selectedDef:null,liveMode:false,autoAddCaseKey:true,selectionMode:false,selectedItems:new Set()};
const defs=new Map(catalogData.items.map(([id,className,name,category])=>[id,{id,className,name,category}]));
const categories=catalogData.categories;
const esc=s=>String(s??"").replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const num=(v,d=0)=>Number.isFinite(Number(v))?Number(v):d;
function itemName(item){return S.schemaItems.find(x=>x.id===item.def_index)?.name||defs.get(item.def_index)?.name||"Unknown item · #"+item.def_index}
function localize(token){return S.translations[token]||token||""}
function parseLocalization(text){const root=parseKV(text),lang=get(root,"lang")||root,tokens=get(lang,"Tokens")||[];for(const [k,v] of tokens)if(typeof v==="string")S.translations[k]=v;for(const item of S.schemaItems)if(item.itemNameToken&&S.translations[item.itemNameToken])item.name=S.translations[item.itemNameToken];for(const kit of S.paintKits)if(kit.token&&S.translations[kit.token])kit.name=S.translations[kit.token];return Object.keys(S.translations).length}
function itemCategory(item){return defs.get(item.def_index)?.category||S.schemaItems.find(x=>x.id===item.def_index)?.category||S.onlineCatalogItems.find(x=>x.id===item.def_index)?.category||"other"}
function parseItem(id,pairs){return {lowId:num(id),inventory:num(get(pairs,"inventory")),def_index:num(get(pairs,"def_index")),level:num(get(pairs,"level"),1),quality:num(get(pairs,"quality")),flags:num(get(pairs,"flags")),origin:num(get(pairs,"origin")),in_use:num(get(pairs,"in_use")),rarity:num(get(pairs,"rarity")),attributes:(get(pairs,"attributes")||[]).map(([k,v])=>({def_index:num(k),value:String(v)})),equipped_state:(get(pairs,"equipped_state")||[]).map(([k,v])=>({class_id:num(k),slot_id:num(v)})),_pairs:pairs}}
function parseInventory(text){const root=parseKV(text),items=get(root,"items");if(!items)throw Error('This file does not contain an "items" section.');S.root=root;S.defaultEquips=get(root,"default_equips")||[];S.items=items.map(([id,p])=>parseItem(id,p));S.inventoryFile=true;S.loaded=true;S.dirtyI=false}
function syncItemPairs(item){const p=item._pairs||[];for(const k of ["inventory","def_index","level","quality","flags","origin","in_use","rarity"])set(p,k,String(item[k]??0));set(p,"attributes",item.attributes.map(a=>[String(a.def_index),String(a.value)]));set(p,"equipped_state",item.equipped_state.map(e=>[String(e.class_id),String(e.slot_id)]));return p}
function inventoryText(){const root=S.root.length?S.root:[];const rows=S.items.map(item=>[String(item.lowId),syncItemPairs(item)]);set(root,"items",rows);set(root,"default_equips",S.defaultEquips||[]);return stringifyKV(root)+"\n"}
function configText(){return stringifyKV(S.config)+"\n"}
function markConfig(k,v){set(S.config,k,String(v));S.dirtyC=true}
function configValue(k,fallback=""){return get(S.config,k)??fallback}
function parseSchema(text){const parsed=parseLegacySchema(text,{definitions:defs,translations:S.translations});S.schemaItems=parsed.items;S.paintKits=parsed.paintKits;return S.schemaItems.length}
function iconFor(category){return categories.find(c=>c.id===category)?.emoji||"◇"}
function itemIcon(item){const category=itemCategory(item);return S.onlineCatalogueData?inventoryArtwork({...item,category},item.attributes||[],S.onlineCatalogueData):""}
function catalogImage(id,item=null){if(item?.artwork)return item.artwork;if(!S.onlineCatalogueData)return "";const category=item?.category||defs.get(Number(id))?.category;return inventoryArtwork({def_index:item?.defIndex??id,category},item?.kitIndex!=null?[{def_index:category==="music"?166:113,value:String(item.kitIndex)}]:[],S.onlineCatalogueData)}
async function loadLegacySkins(){if(S.legacySkins)return S.legacySkins;await loadDefaultIconManifest(false);return S.legacySkins||[]}
async function loadDefaultIconManifest(refreshInventory=true){
 if(!S.onlineCataloguePromise)S.onlineCataloguePromise=loadOnlineCatalogue().then(data=>{S.onlineCatalogueData=data;S.onlineCatalogItems=data.items;S.legacySkins=data.legacySkins;return data}).catch(error=>{S.onlineCataloguePromise=null;console.warn("Complete CS:GO item catalogue could not be loaded:",error);return null});
 await S.onlineCataloguePromise;
 if(refreshInventory&&S.loaded&&S.page==="inventory")render();
}

function itemCard(item){const cat=itemCategory(item),rarity=Math.min(7,Math.max(0,item.rarity)),url=itemIcon(item),selected=S.selectedItems.has(item.lowId);const art=url?'<img class="item-thumb" src="'+esc(url)+'" alt="" loading="lazy" onerror="this.remove()">' :'<div class="art-missing" aria-label="Artwork unavailable"></div>';return '<article class="item '+(selected?'item-selected':'')+'" '+(S.selectionMode?'data-select-card="'+item.lowId+'" role="checkbox" aria-checked="'+selected+'" tabindex="0"':'')+'><div class="visual"><span class="rarity r'+rarity+'"></span><span class="id">#'+item.lowId+'</span>'+art+'</div><div class="item-body">'+(S.selectionMode?'<label class="item-select"><input type="checkbox" data-select-item="'+item.lowId+'" '+(selected?'checked':'')+'> Select item</label>':'')+'<b>'+esc(itemName(item))+'</b><small>'+esc(cat)+' · Def '+item.def_index+' · Quality '+item.quality+'</small><div class="item-actions">'+(S.selectionMode?'':'<button data-edit="'+item.lowId+'">Edit details</button><button class="remove" data-remove="'+item.lowId+'">Remove</button>')+'</div></div></article>'}
function inventoryPage(){const rows=S.items.filter(x=>(S.filter==="all"||itemCategory(x)===S.filter)&&(`${itemName(x)} ${x.def_index} ${x.lowId}`.toLowerCase().includes(S.search.toLowerCase())));return `<div class="toolbar"><div><h2>My inventory <span class="count">${S.items.length}</span></h2><p>Browse and edit the items in your inventory.</p></div><div class="actions"><input id="search" class="search" placeholder="Search inventory..." value="${esc(S.search)}"><button class="btn secondary" id="toggle-select">${S.selectionMode?"Cancel selection":"Select items"}</button><button class="btn primary" id="add">＋ Add item</button></div></div>${S.selectionMode?`<div class="bulk-actions"><span><b>${S.selectedItems.size}</b> selected</span><div><button class="btn secondary" id="select-visible">Select all shown</button><button class="btn secondary" id="clear-selection">Clear</button><button class="btn danger" id="delete-selected" ${S.selectedItems.size?"":"disabled"}>Delete selected</button></div></div>`:""}<div class="filters">${["all",...categories.map(c=>c.id)].map(x=>`<button data-filter="${x}" class="${S.filter===x?"selected":""}">${x==="all"?"All items":categories.find(c=>c.id===x)?.name}</button>`).join("")}</div><div class="inventory-scroll"><div class="grid">${rows.map(itemCard).join("")||'<div class="empty">No items match this view. Try another category or add an item.</div>'}</div></div><div class="default-equips"><div><b>Default equipment</b><small>Team and slot defaults stored in inventory.txt</small></div><button class="btn secondary" id="edit-default-equips">Edit defaults</button></div>`}
const configFields=[
 {key:"competitive_rank",label:"Competitive rank",group:"Ranks",min:0,max:18},{key:"competitive_wins",label:"Competitive wins",group:"Ranks",min:0,max:99999},
 {key:"wingman_rank",label:"Wingman rank",group:"Ranks",min:0,max:18},{key:"wingman_wins",label:"Wingman wins",group:"Ranks",min:0,max:99999},
 {key:"dangerzone_rank",label:"Danger Zone rank",group:"Ranks",min:0,max:15},{key:"dangerzone_wins",label:"Danger Zone wins",group:"Ranks",min:0,max:99999},
 {key:"player_level",label:"Player level",group:"Profile",min:0,max:40},{key:"player_cur_xp",label:"Current XP",group:"Profile",min:0,max:5000},
 {key:"cmd_friendly",label:"Friendly commendations",group:"Commendations",min:0,max:99999},{key:"cmd_teaching",label:"Teaching commendations",group:"Commendations",min:0,max:99999},{key:"cmd_leader",label:"Leader commendations",group:"Commendations",min:0,max:99999},
 {key:"vac_banned",label:"VAC ban",group:"Account",type:"boolean"},{key:"country",label:"Country / region",group:"Account",type:"country"},{key:"currency",label:"Steam currency",group:"Account",type:"currency"},
 {key:"destroy_used_items",label:"Destroy used items (0 / 1)",group:"GC settings",min:0,max:1},{key:"appid_override",label:"App ID override",group:"GC settings",min:0,max:9999999},{key:"show_csgo_gc_servers_only",label:"Only show csgo_gc servers (0 / 1)",group:"GC settings",min:0,max:1},{key:"log_output",label:"Log output (0–2)",group:"GC settings",min:0,max:2},{key:"item_schema_path",label:"Item schema path",group:"GC settings",type:"text"},{key:"inventory_editor_origin",label:"Inventory editor origin",group:"GC settings",type:"text"}
];
const steamCurrencies=[
 [1,"USD","US Dollar"],[2,"GBP","British Pound"],[3,"EUR","Euro"],[4,"CHF","Swiss Franc"],[5,"RUB","Russian Ruble"],[6,"PLN","Polish Złoty"],[7,"BRL","Brazilian Real"],[8,"JPY","Japanese Yen"],[9,"NOK","Norwegian Krone"],[10,"IDR","Indonesian Rupiah"],[11,"MYR","Malaysian Ringgit"],[12,"PHP","Philippine Peso"],[13,"SGD","Singapore Dollar"],[14,"THB","Thai Baht"],[15,"VND","Vietnamese Đồng"],[16,"KRW","South Korean Won"],[17,"TRY","Turkish Lira"],[18,"UAH","Ukrainian Hryvnia"],[19,"MXN","Mexican Peso"],[20,"CAD","Canadian Dollar"],[21,"AUD","Australian Dollar"],[22,"NZD","New Zealand Dollar"],[23,"CNY","Chinese Yuan"],[24,"INR","Indian Rupee"],[25,"CLP","Chilean Peso"],[26,"PEN","Peruvian Sol"],[27,"COP","Colombian Peso"],[28,"ZAR","South African Rand"],[29,"HKD","Hong Kong Dollar"],[30,"TWD","New Taiwan Dollar"],[31,"SAR","Saudi Riyal"],[32,"AED","UAE Dirham"],[33,"SEK","Swedish Krona"],[34,"ARS","Argentine Peso"],[35,"ILS","Israeli New Shekel"],[36,"BYN","Belarusian Ruble"],[37,"KZT","Kazakhstani Tenge"],[38,"KWD","Kuwaiti Dinar"],[39,"QAR","Qatari Riyal"],[40,"CRC","Costa Rican Colón"],[41,"UYU","Uruguayan Peso"],[42,"BGN","Bulgarian Lev"],[43,"HRK","Croatian Kuna"],[44,"CZK","Czech Koruna"],[45,"DKK","Danish Krone"],[46,"HUF","Hungarian Forint"],[47,"RON","Romanian Leu"]
];
const countryCodes="AD AE AF AG AI AL AM AO AQ AR AS AT AU AW AX AZ BA BB BD BE BF BG BH BI BJ BL BM BN BO BQ BR BS BT BV BW BY BZ CA CC CD CF CG CH CI CK CL CM CN CO CR CU CV CW CX CY CZ DE DJ DK DM DO DZ EC EE EG EH ER ES ET FI FJ FK FM FO FR GA GB GD GE GF GG GH GI GL GM GN GP GQ GR GS GT GU GW GY HK HM HN HR HT HU ID IE IL IM IN IO IQ IR IS IT JE JM JO JP KE KG KH KI KM KN KP KR KW KY KZ LA LB LC LI LK LR LS LT LU LV LY MA MC MD ME MF MG MH MK ML MM MN MO MP MQ MR MS MT MU MV MW MX MY MZ NA NC NE NF NG NI NL NO NP NR NU NZ OM PA PE PF PG PH PK PL PM PN PR PS PT PW PY QA RE RO RS RU RW SA SB SC SD SE SG SH SI SJ SK SL SM SN SO SR SS ST ST SV SX SY SZ TC TD TF TG TH TJ TK TL TM TN TO TR TT TV TW TZ UA UG UM US UY UZ VA VC VE VG VI VN VU WF WS YE YT ZA ZM ZW".split(" ");
const countryOptions=countryCodes.map(code=>{let name=code;try{name=new Intl.DisplayNames(["en"],{type:"region"}).of(code)||code}catch{}return {code,name}}).sort((a,b)=>a.name.localeCompare(b.name));

function profilePage(){
 const ranks=get(S.config,"ranks")||[],weights=get(S.config,"rarity_weights")||[];
 const defaults={competitive_rank:"0",competitive_wins:"0",wingman_rank:"0",wingman_wins:"0",dangerzone_rank:"0",dangerzone_wins:"0",player_level:"0",player_cur_xp:"0",vac_banned:"0",cmd_friendly:"0",cmd_teaching:"0",cmd_leader:"0",country:"GB",currency:"2",destroy_used_items:"1",appid_override:"4465480",show_csgo_gc_servers_only:"1",log_output:"1",item_schema_path:"csgo/scripts/items/items_game.txt",inventory_editor_origin:""};
 const fieldMarkup=f=>{
  const value=String(f.group==="Ranks"?get(ranks,f.key)??"":configValue(f.key,defaults[f.key]??""));
  let control="";
  if(f.type==="boolean"){
   control='<select data-config="'+f.key+'"><option value="0" '+(value==="0"?"selected":"")+'>0 — No</option><option value="1" '+(value==="1"?"selected":"")+'>1 — Yes</option></select>';
  }else if(f.type==="currency"){
   control='<select data-config="'+f.key+'">'+(steamCurrencies.some(x=>String(x[0])===value)?"":'<option value="'+esc(value)+'" selected>Current value — '+esc(value)+'</option>')+steamCurrencies.map(([id,code,name])=>'<option value="'+id+'" '+(String(id)===value?"selected":"")+'>'+code+' — '+name+' (ID '+id+')</option>').join("")+'</select>';
  }else if(f.type==="country"){
   control='<select data-config="'+f.key+'">'+(countryOptions.some(x=>x.code===value)?"":'<option value="'+esc(value)+'" selected>Current value — '+esc(value)+'</option>')+countryOptions.map(x=>'<option value="'+x.code+'" '+(x.code===value?"selected":"")+'>'+esc(x.name)+' ('+x.code+')</option>').join("")+'</select>';
  }else{
   control='<input data-config="'+f.key+'" type="'+(f.type||"number")+'" '+(f.min!==undefined?'min="'+f.min+'" max="'+f.max+'"':"")+' value="'+esc(value)+'">';
  }
  const hint=f.key==="player_level"?"Maximum level: 40":f.type==="country"?"Stored as a two-letter ISO country code.":f.type==="currency"?"Stored as Steam's numeric currency ID.":f.type==="boolean"?"Choose whether this account is VAC banned.":"";
  return '<label class="field"><span>'+esc(f.label)+'</span>'+control+(hint?'<small class="field-hint">'+hint+'</small>':"")+'</label>';
 };
 return '<div class="toolbar"><div><h2>Player & GC configuration</h2><p>Configure account details, player progression and Game Coordinator settings.</p></div><span class="pill">CONFIG.TXT</span></div><div class="config-groups">'+["Ranks","Profile","Commendations","Account","GC settings"].map(group=>'<section class="config-group"><h3>'+group+'</h3><div class="settings">'+configFields.filter(f=>f.group===group).map(fieldMarkup).join("")+'</div></section>').join("")+'<section class="config-group"><h3>Rarity weights</h3><p class="muted">These control the random rarity weighting in csgo_gc. Existing entries are preserved.</p><div class="settings">'+["1","2","3","4","5","6","99"].map((k,i)=>'<label class="field"><span>'+["Common","Uncommon","Rare","Mythical","Legendary","Ancient","Unusual"][i]+' (rarity '+k+')</span><input data-weight="'+k+'" type="number" min="0" value="'+esc(get(weights,k)??["10000000","2000000","400000","80000","16000","3200","1280"][i])+'"></label>').join("")+'</div></section></div><div class="notice">Changing any setting here marks <b>config.txt</b> as modified. Currency values use Steam currency IDs; country values use ISO two-letter country codes. When exporting, download and replace both files. Other config keys are preserved.</div>';
}
function connectionPage(){return `<div class="panel"><div class="panel-top"><div><h2>Live game connection</h2><p>Connect to the local csgo_gc inventory editor server.</p></div><span class="pill ${S.conn?.connected?"green":""}">${S.conn?.connected?"CONNECTED":"DISCONNECTED"}</span></div><div class="endpoint">ws://127.0.0.1:13001</div><p class="muted">In your csgo_gc config.txt, set inventory_editor_origin to this site's exact origin, e.g. <code>https://your-project.vercel.app</code>. Restart the GC after changing it.</p><div class="actions"><button class="btn primary" id="connect" ${S.conn?.connected?"disabled":""}>${S.conn?.connected?"Connected":"Connect to GC"}</button><button class="btn secondary" id="disconnect">Disconnect</button></div><div class="notice">Browser security may block an HTTPS Vercel page from opening a local insecure ws:// connection. If that happens, offline editing still works. A local HTTPS/WSS bridge would be needed for browsers that enforce this restriction.</div><div id="live-message" class="muted"></div></div>`}
function welcome(){return `<div class="welcome"><div class="hero-icon">▤</div><div class="eyebrow">YOUR LOCAL WORKSPACE</div><h2>Build the inventory you want.</h2><p>Start with a new inventory or load an existing inventory.txt. The built-in item catalogue is ready to use — no game files or schema import required.</p><div class="actions"><button class="btn primary" id="new-inventory">Start empty inventory</button><button class="btn secondary" id="load-start">Load existing files</button><button class="btn secondary" id="connect-start">Connect live</button></div><small>Your files stay in this browser. They are never uploaded to this website.</small></div>`}
function render(){const root=$("#app");root.innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><span class="brand-mark">B</span><div><b>BETTER INVENTORY</b><small>CS:GO LEGACY</small></div></div><nav><button class="nav ${S.page==="inventory"?"active":""}" data-page="inventory">▦ <span>Inventory</span></button><button class="nav ${S.page==="profile"?"active":""}" data-page="profile">♙ <span>Player profile</span></button><button class="nav ${S.page==="connection"?"active":""}" data-page="connection">⌁ <span>Live connection</span></button><button class="nav ${S.page==="settings"?"active":""}" data-page="settings">⚙ <span>Settings</span></button></nav><div class="side-status"><i class="${S.conn?.connected?"online":""}"></i>${S.conn?.connected?"Connected to GC":"Offline editing"}</div></aside><main><header><div><div class="eyebrow">CS:GO LEGACY / INVENTORY TOOL</div><h1>${({inventory:"Inventory","add-item":"Add inventory items",profile:"Player profile",connection:"Live connection",settings:"Settings"})[S.page]}</h1></div><div class="head-actions"><span class="pill ${S.conn?.connected?"green":""}">${S.conn?.connected?"● LIVE":"● OFFLINE"}</span><button class="btn secondary" id="load">Load files</button><button class="btn primary" id="save">Export changes</button></div></header><section id="content">${!S.loaded&&!S.conn?.connected?welcome():({inventory:inventoryPage,"add-item":()=>`<div id="add-item-page"></div>`,profile:profilePage,connection:connectionPage,settings:settingsPage})[S.page]()}</section></main></div><div id="modal"></div>`;
$("#load").onclick=loadModal;$("#save").onclick=saveModal;$("#load-start")?.addEventListener("click",loadModal);$("#new-inventory")?.addEventListener("click",startNewInventory);$("#connect-start")?.addEventListener("click",connect);document.querySelectorAll("[data-page]").forEach(b=>b.onclick=()=>showPage(b.dataset.page));wire(S.page)}
function settingsPage(){return `<div class="toolbar"><div><h2>Editor settings</h2><p>The built-in catalogue is ready immediately. A local game schema is optional and can add further definitions and paint kits.</p></div></div><div class="panel"><h3>Import items_game.txt</h3><p class="muted">Load the schema from your CS:GO Legacy installation. The editor reads it locally and uses item definitions to expand the Add Item catalogue.</p><label class="file">Select items_game.txt<input type="file" id="schema-file" accept=".txt,text/plain"></label><label class="file">Select csgo_english.txt (optional, for friendly names)<input type="file" id="language-file" accept=".txt,text/plain"></label><p class="muted tiny">Item artwork and the full item catalogue load automatically from the category-specific CS:GO inventory data. No manual image manifest is required.</p><label class="check-field"><input type="checkbox" id="auto-case-key" ${S.autoAddCaseKey?"checked":""}> Automatically add the matching case key when adding a case</label><div id="schema-status" class="muted">${S.schemaItems.length?S.schemaItems.length+" additional schema definitions loaded.": "Built-in catalogue ready. No local schema needed."}</div><div class="notice">You can add and export items without importing any game files. Schema and localization imports are optional enhancements only; files are parsed locally and never uploaded.</div></div><div class="panel"><h3>Data & privacy</h3><p class="muted">Inventory and config files are stored in this page's memory only. Refreshing the page clears them. Exports are generated locally using your browser's download feature.</p><button class="btn secondary" id="clear-data">Clear loaded data</button></div>`}
function startNewInventory(){S.root=[];S.items=[];S.defaultEquips=[];S.loaded=true;S.inventoryFile=false;S.configFile=false;S.dirtyI=true;S.dirtyC=false;S.page="inventory";render();toast("New inventory ready. Add items from the built-in catalogue.")}
function showPage(p){S.page=p;render()}
function wire(p){if(p==="inventory"){const defaults=$("#edit-default-equips");if(defaults)defaults.onclick=defaultEquipsModal;const add=$("#add");if(add)add.onclick=addModal;const search=$("#search");if(search)search.oninput=()=>{S.search=search.value;$("#content").innerHTML=inventoryPage();wire("inventory")};document.querySelectorAll("[data-filter]").forEach(b=>b.onclick=()=>{S.filter=b.dataset.filter;$("#content").innerHTML=inventoryPage();wire("inventory")});const toggle=$("#toggle-select");if(toggle)toggle.onclick=()=>{S.selectionMode=!S.selectionMode;S.selectedItems.clear();render()};const inventoryGrid=$(".grid");if(inventoryGrid)inventoryGrid.onclick=e=>{if(!S.selectionMode||e.target.closest("button,input,a,label"))return;const card=e.target.closest("[data-select-card]");if(!card)return;const id=+card.dataset.selectCard;if(S.selectedItems.has(id))S.selectedItems.delete(id);else S.selectedItems.add(id);$("#content").innerHTML=inventoryPage();wire("inventory")};if(inventoryGrid)inventoryGrid.onkeydown=e=>{if(!S.selectionMode||!(e.key==="Enter"||e.key===" "))return;const card=e.target.closest("[data-select-card]");if(!card||e.target.closest("input,button,label"))return;e.preventDefault();const id=+card.dataset.selectCard;if(S.selectedItems.has(id))S.selectedItems.delete(id);else S.selectedItems.add(id);$("#content").innerHTML=inventoryPage();wire("inventory")};document.querySelectorAll("[data-select-item]").forEach(b=>b.onchange=()=>{const id=+b.dataset.selectItem;if(b.checked)S.selectedItems.add(id);else S.selectedItems.delete(id);$("#content").innerHTML=inventoryPage();wire("inventory")});const all=$("#select-visible");if(all)all.onclick=()=>{S.items.filter(x=>(S.filter==="all"||itemCategory(x)===S.filter)&&(`${itemName(x)} ${x.def_index} ${x.lowId}`.toLowerCase().includes(S.search.toLowerCase()))).forEach(x=>S.selectedItems.add(x.lowId));$("#content").innerHTML=inventoryPage();wire("inventory")};const clear=$("#clear-selection");if(clear)clear.onclick=()=>{S.selectedItems.clear();$("#content").innerHTML=inventoryPage();wire("inventory")};const del=$("#delete-selected");if(del)del.onclick=deleteSelectedItems;document.querySelectorAll("[data-edit]").forEach(b=>b.onclick=()=>editModal(+b.dataset.edit));document.querySelectorAll("[data-remove]").forEach(b=>b.onclick=()=>removeItem(+b.dataset.remove))}
 if(p==="profile"){document.querySelectorAll("[data-config]").forEach(i=>i.onchange=()=>{const f=configFields.find(x=>x.key===i.dataset.config);if(f?.min!==undefined&&f?.max!==undefined&&(!Number.isInteger(+i.value)||+i.value<f.min||+i.value>f.max)){alert("Enter a value between "+f.min+" and "+f.max+".");i.value=configValue(i.dataset.config,"0");return}if(["competitive_rank","competitive_wins","wingman_rank","wingman_wins","dangerzone_rank","dangerzone_wins"].includes(i.dataset.config)){const r=get(S.config,"ranks")||[];set(r,i.dataset.config,i.value);set(S.config,"ranks",r)}else markConfig(i.dataset.config,i.value);S.dirtyC=true});document.querySelectorAll("[data-weight]").forEach(i=>i.onchange=()=>{const w=get(S.config,"rarity_weights")||[];set(w,i.dataset.weight,i.value);set(S.config,"rarity_weights",w);S.dirtyC=true})}
 if(p==="connection"){$("#connect").onclick=connect;$("#disconnect").onclick=()=>{S.conn?.disconnect();S.conn=null;render()}}
 if(p==="settings"){$("#auto-case-key").onchange=e=>{S.autoAddCaseKey=e.target.checked};$("#schema-file").onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const n=parseSchema(await f.text());$("#schema-status").textContent=n+" item definitions and "+S.paintKits.length+" paint kits loaded from "+f.name+".";toast("Game schema loaded")}catch(err){alert("Could not read schema: "+err.message)}};$("#language-file").onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const n=parseLocalization(await f.text());$("#schema-status").textContent=n+" localized item names loaded.";toast("English localization loaded")}catch(err){alert("Could not read localization: "+err.message)}};$("#clear-data").onclick=()=>{if(confirm("Clear loaded inventory and config data from this page?")){S.items=[];S.root=[];S.defaultEquips=[];S.config=[];S.loaded=false;S.inventoryFile=false;S.configFile=false;S.dirtyI=S.dirtyC=false;render()}}}}
function modal(html){$("#modal").innerHTML=`<div class="shade" id="shade"><div class="modal">${html}</div></div>`;$("#shade").onclick=e=>{if(e.target.id==="shade")$("#modal").innerHTML=""};$("#close")?.addEventListener("click",()=>$("#modal").innerHTML="")}
function loadModal(){modal(`<div class="modal-head"><div><div class="eyebrow">IMPORT FILES</div><h2>Load your files</h2></div><button class="x" id="close">×</button></div><p class="muted">Select your inventory.txt file. config.txt is optional, but needed for profile editing.</p><label class="file">inventory.txt<input id="invfile" type="file" accept=".txt,text/plain"></label><label class="file">config.txt (optional)<input id="cfgfile" type="file" accept=".txt,text/plain"></label><button class="btn primary full" id="import">Import selected files</button>`);$("#import").onclick=async()=>{try{const f=$("#invfile").files[0],c=$("#cfgfile").files[0];if(!f)throw Error("Choose inventory.txt first.");parseInventory(await f.text());if(c){S.config=parseKV(await c.text());S.configFile=true;S.dirtyC=false}else{S.config=[];S.configFile=false}$("#modal").innerHTML="";S.page="inventory";render();toast("Files loaded successfully")}catch(e){alert("Unable to load files: "+e.message)}}}
async function addModal(){S.selectedDef=null;S.page="add-item";render();$("#content").innerHTML=`<div class="add-page"><div class="toolbar add-toolbar"><div><div class="eyebrow">ITEM CATALOGUE</div><h2>Add inventory items</h2><p>Browse actual CS:GO Legacy artwork, choose a weapon finish, then add it to your inventory.</p></div><div class="actions"><button class="btn secondary" id="back-inventory">← Back to inventory</button></div></div><div class="add-catalog-panel"><input id="catalog-search" class="search wide" placeholder="Search by item name or definition index..."><div id="catalog-breadcrumb" class="catalog-breadcrumb"></div><div id="catalog-categories" class="category-tiles"></div><div id="catalog-results" class="catalog-results"></div></div><div class="add-config-panel"><div class="custom-def"><input id="custom-def" type="number" min="1" placeholder="Or enter a custom def_index"><button class="btn secondary" id="choose-custom">Use definition</button></div><div id="chosen" class="chosen muted">Choose an item to configure it.</div><div id="case-key-note" class="muted tiny"></div><div id="case-quantity-wrap" class="field case-quantity" hidden><span>Number of cases to add (1–100)</span><input id="case-quantity" type="number" min="1" max="100" step="1" value="1"></div><div class="settings compact"><label class="field"><span>Quality</span><input id="new-quality" type="number" value="4"></label><label class="field"><span>Rarity</span><input id="new-rarity" type="number" value="3" min="0" max="99"></label><label class="field"><span>Level</span><input id="new-level" type="number" value="1"></label><label class="field"><span>Origin</span><input id="new-origin" type="number" value="24"></label></div><div class="settings compact"><label class="field"><span>Paint kit (optional)</span><select id="new-paint"><option value="">No paint</option>${S.paintKits.map(k=>`<option value="${k.id}">${esc(k.name)} · #${k.id}</option>`).join("")}</select></label><label class="field"><span>Wear (0–1)</span><input id="new-wear" type="number" min="0" max="1" step="0.000001" value="0.06"></label><label class="field"><span>Paint seed</span><input id="new-seed" type="number" min="0" max="1000" value="0"></label><label class="field"><span>StatTrak counter</span><input id="new-stattrak" type="number" min="0" value="0"></label></div><label class="check-field"><input id="new-is-stattrak" type="checkbox"> Add StatTrak attribute (quality 9)</label><button class="btn primary full" id="create-item" disabled>Add to inventory</button><p class="muted tiny">The built-in catalogue works without imports. Optionally load items_game.txt in Settings to supplement it with additional definitions and paint kits.</p></div></div>`;$("#back-inventory").onclick=()=>{S.page="inventory";render()};const search=$("#catalog-search");
const weaponTypes=[
 {id:"rifles",name:"Rifles",icon:"🎯"},
 {id:"snipers",name:"Sniper Rifles",icon:"🔭"},
 {id:"smgs",name:"SMGs",icon:"⚡"},
 {id:"shotguns",name:"Shotguns",icon:"💥"},
 {id:"machineguns",name:"Machine Guns",icon:"🔥"},
 {id:"pistols",name:"Pistols",icon:"🔫"},
 {id:"knives",name:"Knives",icon:"🔪"}
];
const rootTypes=[
 {id:"weapons",name:"Weapons",icon:"🎯",description:"Choose a weapon type, then its finish"},
 {id:"cases",name:"Cases",icon:"📦",description:"Weapon cases and standard containers"},
 {id:"souvenir",name:"Souvenir Packages",icon:"🎁",description:"Tournament souvenir packages"},
 {id:"gloves",name:"Gloves",icon:"🧤",description:"Glove models and finishes"},
 {id:"agents",name:"Agents",icon:"🪖",description:"CT and T agent models"},
 {id:"music",name:"Music Kits",icon:"🎵",description:"Equip a music kit"},
 {id:"stickers",name:"Stickers",icon:"🏷️",description:"Stickers and capsules"},
 {id:"extras",name:"Keys & Extras",icon:"🗝️",description:"Keys, patches and other containers"}
];
const extraTypes=[
 {id:"keys",name:"Keys",icon:"🗝️"},
 {id:"patches",name:"Patches",icon:"🧵"},
 {id:"containers",name:"Other Containers",icon:"🧰"},
 {id:"other",name:"Other Items",icon:"◇"}
];
let currentCategory=null,currentSubcategory=null;
const allCatalogItems=()=>{const map=new Map();for(const item of [...defs.values(),...S.schemaItems,...S.onlineCatalogItems]){const key=item.catalogKey||"def:"+item.id;map.set(key,{...item,catalogKey:key})}return [...map.values()]};
const selectedCatalogItem=()=>allCatalogItems().find(x=>x.catalogKey===S.selectedDef)||(S.selectedDef==null?null:{id:Number(String(S.selectedDef).replace(/^def:/,"")),name:"Custom definition #"+String(S.selectedDef).replace(/^def:/,""),category:"other",defaultQuality:4,defaultRarity:3,catalogKey:S.selectedDef});
let activeWeapon=null,activeSkins=[],selectedSkin=null;
const isSkinBase=x=>!!x&&["rifles","snipers","smgs","shotguns","machineguns","pistols","knives","gloves"].includes(x.category);
const isSouvenir=x=>/souvenir/i.test(String(x.containerType||"")+" "+String(x.name||""));
const isCase=x=>!isSouvenir(x)&&(!x.containerType||/case/i.test(x.containerType)||/case/i.test(x.name||""));
const itemsFor=(category,subcategory)=>allCatalogItems().filter(x=>{
 if(category==="weapons")return !!subcategory&&x.category===subcategory;
 if(category==="cases")return x.category==="cases"&&isCase(x);
 if(category==="souvenir")return x.category==="cases"&&isSouvenir(x);
 if(category==="extras"){
  if(subcategory==="containers")return x.category==="cases"&&!isCase(x)&&!isSouvenir(x);
  return x.category===(subcategory||"other");
 }
 return x.category===category;
});
const tile=(item,count)=>'<button class="category-tile" data-category-tile="'+esc(item.id)+'"><span class="category-icon">'+item.icon+'</span><b>'+esc(item.name)+'</b><small>'+esc(item.description||"Browse "+item.name.toLowerCase())+'</small><span class="category-count">'+count+' items</span><span class="category-arrow">›</span></button>';
const renderBrowse=()=>{
 const q=search.value.trim().toLowerCase(),all=allCatalogItems();
 const crumb=[];
 if(currentCategory){const root=rootTypes.find(x=>x.id===currentCategory);if(root)crumb.push(root.name)}
 if(currentSubcategory){const sub=[...weaponTypes,...extraTypes].find(x=>x.id===currentSubcategory);if(sub)crumb.push(sub.name)}
 $("#catalog-breadcrumb").innerHTML=(currentCategory?'<button class="breadcrumb-back" data-browse-back="1">← '+(currentSubcategory?"Back to "+(rootTypes.find(x=>x.id===currentCategory)?.name||"category"):"All categories")+'</button>':"")+'<span>'+(q?"Search results":crumb.join(" / ")||"Choose a category")+'</span>';
 $("#catalog-categories").hidden=!!q;
 $("#catalog-results").hidden=false;
 if(q){
  const matches=all.filter(x=>(x.name+" "+x.className+" "+x.id+" "+(x.kitIndex??"")+" "+(x.containerType||"")).toLowerCase().includes(q));
  $("#catalog-results").innerHTML=matches.map(x=>catalogRow(x,true)).join("")||'<div class="empty">No items match that search.</div>';
  return;
 }
 if(!currentCategory){
  $("#catalog-categories").innerHTML=rootTypes.map(x=>tile(x, x.id==="weapons"?all.filter(y=>weaponTypes.some(w=>w.id===y.category)).length:x.id==="extras"?all.filter(y=>["keys","patches","other"].includes(y.category)||(y.category==="cases"&&!isCase(y)&&!isSouvenir(y))).length:itemsFor(x.id).length)).join("");
  $("#catalog-results").innerHTML='<div class="catalog-hint">Select a category above to browse its items.</div>';
  return;
 }
 if((currentCategory==="weapons"||currentCategory==="extras")&&!currentSubcategory){
  const subs=currentCategory==="weapons"?weaponTypes:extraTypes;
  $("#catalog-categories").innerHTML=subs.map(x=>tile(x,itemsFor(currentCategory,x.id).length)).join("");
  $("#catalog-results").innerHTML='<div class="catalog-hint">Choose a subcategory to see the available items.</div>';
  return;
 }
 $("#catalog-categories").hidden=true;
 const rows=itemsFor(currentCategory,currentSubcategory);
 $("#catalog-results").innerHTML=rows.map(x=>catalogRow(x,false)).join("")||'<div class="empty">No items are available in this category yet.</div>';
};
function catalogRow(x,showCategory){
 const art=catalogImage(x.id,x);
 const label=showCategory?(categories.find(c=>c.id===x.category)?.name||x.category):"";
 return '<button class="catalog-row" data-catalog-key="'+esc(x.catalogKey)+'"><span class="catalog-icon">'+(art?'<img src="'+esc(art)+'" alt="" loading="lazy" onerror="this.remove()">':iconFor(x.category))+'</span><span><b>'+esc(x.name)+'</b><small>'+esc([label,x.containerType,x.kitIndex!=null?"Kit #"+x.kitIndex:"Def #"+x.id].filter(Boolean).join(" · "))+'</small></span><span class="row-arrow">＋</span></button>';
}
const renderWeaponSkins=async weapon=>{
 activeWeapon=weapon;selectedSkin=null;$("#catalog-categories").hidden=true;
 $("#catalog-breadcrumb").innerHTML='<button class="breadcrumb-back" data-skin-back="1">← Back to '+esc(weaponTypes.find(x=>x.id===weapon.category)?.name||"Weapons")+'</button><span>'+esc(weapon.name)+" / Finishes"+'</span>';
 $("#catalog-results").innerHTML='<div class="empty">Loading CS:GO Legacy finishes…</div>';
 try{
  const all=await loadLegacySkins();
  const matching=all.filter(s=>Number(s.weapon?.weapon_id)===Number(weapon.id)&&s.paint_index!=null);
  const unique=new Map();
  for(const skin of matching){const id=Number(skin.paint_index);if(!Number.isInteger(id)||id<1)continue;const previous=unique.get(id);if(!previous||(!skin.stattrak&&!skin.souvenir))unique.set(id,skin)}
  activeSkins=[...unique.values()].sort((a,b)=>String(a.name).localeCompare(String(b.name)));
  const imageUrl=s=>S.onlineCatalogueData?.skins?.[Number(s.weapon?.weapon_id)+":"+Number(s.paint_index)]||(typeof s.image==="string"&&s.image.startsWith("https://community.akamai.steamstatic.com/economy/image/")?s.image:"");
  $("#catalog-results").innerHTML='<button class="catalog-row" data-skin="vanilla"><span class="catalog-icon">'+(catalogImage(weapon.id,weapon)?'<img src="'+esc(catalogImage(weapon.id,weapon))+'" alt="" loading="lazy" onerror="this.remove()">':"")+'</span><span><b>'+esc(weapon.name)+' (Vanilla)</b><small>No paint finish</small></span><span class="row-arrow">＋</span></button>'+activeSkins.map((skin,i)=>'<button class="catalog-row skin-row" data-skin="'+i+'"><span class="skin-thumb">'+(imageUrl(skin)?'<img src="'+esc(imageUrl(skin))+'" alt="" loading="lazy" onerror="this.remove()">':"")+'</span><span><b>'+esc(skin.name)+'</b><small>'+esc(skin.rarity?.name||"Finish")+' · Paint kit #'+Number(skin.paint_index)+'</small></span><span class="row-arrow">＋</span></button>').join("")+(activeSkins.length?"":'<div class="empty">No Legacy finishes were found for this weapon.</div>');
 }catch(error){activeSkins=[];$("#catalog-results").innerHTML='<div class="empty">Could not load the skin catalogue. '+esc(error.message)+'</div>'}
};
const chooseSkin=skin=>{
 const paintId=skin?Number(skin.paint_index):0;selectedSkin=skin||null;S.selectedDef=activeWeapon.catalogKey||"def:"+activeWeapon.id;
 const select=$("#new-paint");
 if(paintId>0&&!Array.from(select.options).some(o=>Number(o.value)===paintId)){const option=document.createElement("option");option.value=String(paintId);option.textContent=(skin.name||"Selected finish")+" · #"+paintId;select.append(option)}
 select.value=paintId?String(paintId):"";$("#new-quality").value="4";
 const rarity=String(skin?.rarity?.id||"").toLowerCase();
 const rarityValue=rarity.includes("contraband")?7:rarity.includes("covert")?6:rarity.includes("classified")?5:rarity.includes("restricted")?4:rarity.includes("milspec")||rarity.includes("mil_spec")||rarity.includes("mil-spec")?3:rarity.includes("industrial")?2:rarity.includes("consumer")?1:3;
 $("#new-rarity").value=String(rarityValue);$("#new-wear").value=String(skin?.min_float??0.06);
 $("#chosen").textContent=skin?"Selected: "+skin.name+" · "+activeWeapon.name+" (paint kit #"+paintId+")":"Selected: "+activeWeapon.name+" (vanilla)";
 $("#case-key-note").textContent=skin?"Legacy finish selected.":"Vanilla finish selected.";
 $("#create-item").disabled=false;$("#create-item").textContent="Add "+(skin?skin.name:activeWeapon.name)+" to inventory";
};
const matchingCaseKey=()=>{const x=selectedCatalogItem();return x?.category==="cases"&&(!x.containerType||x.containerType==="Case")?findCaseKey(x,allCatalogItems()):null};
search.oninput=renderBrowse;
$("#catalog-categories").onclick=e=>{
 const button=e.target.closest("[data-category-tile]");if(!button)return;
 const id=button.dataset.categoryTile;
 if(rootTypes.some(x=>x.id===id)){currentCategory=id;currentSubcategory=null}
 else currentSubcategory=id;
 renderBrowse();
};
$("#catalog-breadcrumb").onclick=e=>{
 if(e.target.closest("[data-skin-back]")){renderBrowse();return}
 if(!e.target.closest("[data-browse-back]"))return;
 if(currentSubcategory)currentSubcategory=null;else currentCategory=null;
 renderBrowse();
};
$("#catalog-results").onclick=e=>{
 const skinButton=e.target.closest("[data-skin]");
 if(skinButton){if(activeWeapon)chooseSkin(skinButton.dataset.skin==="vanilla"?null:activeSkins[Number(skinButton.dataset.skin)]);return}
 const back=e.target.closest("[data-skin-back]");if(back){renderBrowse();return}
 const button=e.target.closest("[data-catalog-key]");if(!button)return;
 const clicked=allCatalogItems().find(x=>x.catalogKey===button.dataset.catalogKey);if(!clicked)return;
 if(isSkinBase(clicked)){renderWeaponSkins(clicked);return}
 selectedSkin=null;S.selectedDef=clicked.catalogKey;
 const x=selectedCatalogItem(),key=matchingCaseKey();
 $("#chosen").textContent="Selected: "+x.name+" (definition "+x.id+")";
 $("#case-quantity-wrap").hidden=x.category!=="cases"||!isCase(x);
 $("#case-quantity").value="1";
 $("#case-key-note").textContent=x.category==="cases"?(isSouvenir(x)?"Souvenir packages do not require a key.":isCase(x)?(S.autoAddCaseKey?(key?"Matching key will also be added: "+key.name+" (#"+key.id+").":"No matching key definition was found."):"Automatic case-key addition is switched off in Settings."):"This container does not require a key."):"";
 $("#new-quality").value=String(x.defaultQuality??4);$("#new-rarity").value=String(x.defaultRarity??3);
 $("#create-item").disabled=false;$("#create-item").textContent=x.category==="cases"&&isCase(x)&&key&&S.autoAddCaseKey?"Add case + matching key":"Add to inventory";
};
$("#catalog-results").innerHTML='<div class="empty">Loading official CS:GO item artwork…</div>';
await loadDefaultIconManifest(false);renderBrowse();
$("#choose-custom").onclick=()=>{const id=+$("#custom-def").value;if(!Number.isInteger(id)||id<1){alert("Enter a valid definition index.");return}S.selectedDef="def:"+id;$("#chosen").textContent="Custom definition selected: #"+id;$("#case-key-note").textContent="";$("#create-item").textContent="Add to inventory";$("#create-item").disabled=false};$("#create-item").onclick=()=>{
  const selected=selectedCatalogItem();if(!selected)return;
  const quantity=selected.category==="cases"?Number($("#case-quantity").value):1;if(!Number.isInteger(quantity)||quantity<1||quantity>100){alert("Choose a whole number of cases between 1 and 100.");return}
  const makeItem=(definition,lowId,overrides={})=>({lowId,inventory:0,def_index:definition.defIndex??definition.id,level:1,quality:definition.defaultQuality??4,flags:0,origin:24,in_use:0,rarity:definition.defaultRarity??(definition.category==="keys"?1:3),attributes:[],equipped_state:[],_pairs:[],...overrides});
  const item=makeItem(selected,nextLocalId(),{level:num($("#new-level").value,1),quality:num($("#new-quality").value,selected.defaultQuality??4),origin:num($("#new-origin").value,24),rarity:num($("#new-rarity").value,selected.defaultRarity??3)});
  const paint=+$("#new-paint").value;
  if(selected.category==="music"&&selected.kitIndex!=null)item.attributes.push({def_index:166,value:String(selected.kitIndex)});
  if(selected.category==="stickers"&&selected.kitIndex!=null)item.attributes.push({def_index:113,value:String(selected.kitIndex)});
  if(paint){const kit=S.paintKits.find(k=>k.id===paint),min=kit?.min??selectedSkin?.min_float??0,max=kit?.max??selectedSkin?.max_float??1,wear=Math.max(min,Math.min(max,num($("#new-wear").value,0.06)));item.attributes.push({def_index:6,value:String(paint)},{def_index:7,value:String(Math.max(0,Math.min(1000,num($("#new-seed").value))))},{def_index:8,value:String(wear)})}
  if($("#new-is-stattrak").checked){item.quality=9;item.attributes.push({def_index:80,value:String(Math.max(0,num($("#new-stattrak").value)))})}
  const created=[],key=matchingCaseKey(),used=new Set(S.items.map(x=>x.lowId));const allocateId=()=>{let id=1;while(used.has(id))id++;used.add(id);return id};
  if(selected.category==="cases"){for(let i=0;i<quantity;i++){created.push(makeItem(selected,allocateId(),{level:num($("#new-level").value,1),quality:num($("#new-quality").value,selected.defaultQuality??4),origin:num($("#new-origin").value,24),rarity:num($("#new-rarity").value,selected.defaultRarity??3)}));if(S.autoAddCaseKey&&key)created.push(makeItem(key,allocateId()))}}else created.push(item)
  if(S.conn?.connected){try{if(created.length>1)S.conn.createBatch(created);else S.conn.create(item);toast(selected.category==="cases"?quantity+" case"+(quantity===1?"":"s")+(S.autoAddCaseKey&&key?" and "+quantity+" matching key"+(quantity===1?"":"s"):"")+" queued for GC creation.":"Create request sent to the GC. Waiting for confirmation.")}catch(e){alert(e.message);return}}
  else{S.items.push(...created);S.dirtyI=true;toast(selected.category==="cases"?quantity+" case"+(quantity===1?"":"s")+(S.autoAddCaseKey&&key?" and "+quantity+" matching key"+(quantity===1?"":"s"):"")+" added locally.":"Item added locally")}
  S.page="inventory";render();
}};
function defaultEquipsModal(){const data=(S.defaultEquips||[]).map(([id,p])=>({id,class_id:num(get(p,"class_id")),slot_id:num(get(p,"slot_id"))}));modal('<div class="modal-head"><div><div class="eyebrow">INVENTORY CONFIGURATION</div><h2>Default equipment</h2></div><button class="x" id="close">×</button></div><p class="muted">Edit the default class and slot assignments as a JSON array.</p><label class="field json-field"><span>Default equips JSON</span><textarea id="default-equips-json" rows="8">'+esc(JSON.stringify(data,null,2))+'</textarea></label><button class="btn primary full" id="apply-defaults">Apply defaults</button>');$("#apply-defaults").onclick=()=>{try{const rows=JSON.parse($("#default-equips-json").value);if(!Array.isArray(rows)||!rows.every(x=>x.id!==undefined&&Number.isInteger(+x.class_id)&&Number.isInteger(+x.slot_id)))throw Error("Use an array of objects with id, class_id and slot_id.");S.defaultEquips=rows.map(x=>[String(x.id),[["class_id",String(x.class_id)],["slot_id",String(x.slot_id)]]]);S.dirtyI=true;$("#modal").innerHTML="";toast("Default equipment updated")}catch(e){alert(e.message)}}}
function nextLocalId(){let id=1;while(S.items.some(x=>x.lowId===id))id++;return id}
function editModal(id){const x=S.items.find(i=>i.lowId===id);if(!x)return;modal(`<div class="modal-head"><div><div class="eyebrow">ITEM #${id}</div><h2>${esc(itemName(x))}</h2></div><button class="x" id="close">×</button></div><div class="settings compact">${["def_index","inventory","level","quality","flags","origin","in_use","rarity"].map(k=>`<label class="field"><span>${k}</span><input id="edit-${k}" type="number" value="${x[k]??0}"></label>`).join("")}</div><label class="field json-field"><span>Attributes (JSON array)</span><textarea id="edit-attributes" rows="5">${esc(JSON.stringify(x.attributes,null,2))}</textarea></label><label class="field json-field"><span>Equipped state (JSON array)</span><textarea id="edit-equips" rows="3">${esc(JSON.stringify(x.equipped_state,null,2))}</textarea></label><p class="muted tiny">Attribute values are strings. Use attribute definition IDs from the item schema. Equipped entries use class_id and slot_id.</p><button class="btn primary full" id="apply">Apply changes</button>`);$("#apply").onclick=()=>{try{const attrs=JSON.parse($("#edit-attributes").value),equips=JSON.parse($("#edit-equips").value);if(!Array.isArray(attrs)||!attrs.every(a=>Number.isInteger(+a.def_index)&&typeof a.value==="string"))throw Error("Attributes must be an array of {def_index, value} objects.");if(!Array.isArray(equips)||!equips.every(a=>Number.isInteger(+a.class_id)&&Number.isInteger(+a.slot_id)))throw Error("Equipped state must be an array of {class_id, slot_id} objects.");for(const k of ["def_index","inventory","level","quality","flags","origin","in_use","rarity"])x[k]=num($("#edit-"+k).value);x.attributes=attrs.map(a=>({def_index:+a.def_index,value:a.value}));x.equipped_state=equips.map(a=>({class_id:+a.class_id,slot_id:+a.slot_id}));if(S.conn?.connected)S.conn.modify(x);S.dirtyI=true;$("#modal").innerHTML="";render()}catch(e){alert(e.message)}}}
function removeItem(id){const x=S.items.find(i=>i.lowId===id);if(!x||!confirm("Remove "+itemName(x)+" (#"+id+")?"))return;if(S.conn?.connected){try{S.conn.destroy(id)}catch(e){alert(e.message);return}}else{S.items=S.items.filter(i=>i.lowId!==id);S.dirtyI=true}S.selectedItems.delete(id);render()}
function deleteSelectedItems(){const ids=[...S.selectedItems].filter(id=>S.items.some(x=>x.lowId===id));if(!ids.length)return;if(!confirm("Permanently remove "+ids.length+" selected inventory item"+(ids.length===1?"":"s")+"? This cannot be undone unless you reload a backup."))return;if(S.conn?.connected){try{S.conn.destroyBatch(ids);S.selectedItems.clear();S.selectionMode=false;toast("Delete requests queued for "+ids.length+" items. Waiting for GC confirmation.")}catch(e){alert(e.message)}return}const remove=new Set(ids);S.items=S.items.filter(x=>!remove.has(x.lowId));S.selectedItems.clear();S.selectionMode=false;S.dirtyI=true;render();toast(ids.length+" inventory item"+(ids.length===1?"":"s")+" deleted.")}
function saveModal(){if(!S.loaded&&!S.conn?.connected)return alert("Load files or connect to the GC first.");modal(`<div class="modal-head"><div><div class="eyebrow">EXPORT FILES</div><h2>Save your changes</h2></div><button class="x" id="close">×</button></div><div class="notice">${S.dirtyC?"Your config has changed. Download and replace BOTH inventory.txt and config.txt in your csgo_gc folder.":"Download the updated inventory.txt. If you've changed config.txt, make sure you export and replace that file too."}</div><div class="export-row">▤ <b>inventory.txt</b><span>Always included</span></div>${S.dirtyC?'<div class="export-row">⚙ <b>config.txt</b><span>Modified</span></div>':S.configFile?'<div class="export-row">⚙ <b>config.txt</b><span>Not modified</span></div>':""}<button class="btn primary full" id="download">Download changed files</button>`);$("#download").onclick=()=>{if(S.loaded)download("inventory.txt",inventoryText());if(S.dirtyC)download("config.txt",configText());S.dirtyI=S.dirtyC=false;$("#modal").innerHTML="";toast("Export started")}}
function download(name,data){const url=URL.createObjectURL(new Blob([data],{type:"text/plain;charset=utf-8"})),a=document.createElement("a");a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function toast(msg){let el=$("#toast");if(!el){el=document.createElement("div");el.id="toast";document.body.append(el)}el.textContent=msg;el.classList.add("show");clearTimeout(el._timer);el._timer=setTimeout(()=>el.classList.remove("show"),3000)}
function connect(){if(S.conn?.connected){showPage("connection");return}const c=new GCConnection();S.conn=c;c.addEventListener("status",()=>{if(S.page==="connection")render()});c.addEventListener("snapshot",e=>{S.items=e.detail;S.loaded=true;S.liveMode=true;S.inventoryFile=false;S.dirtyI=false;toast("Live inventory synchronized: "+S.items.length+" items");if(S.page==="inventory")render()});c.addEventListener("change",e=>{S.items=e.detail;if(S.page==="inventory")render()});c.addEventListener("created",e=>toast("Item created and confirmed. Assigned ID: "+e.detail.lowId));c.addEventListener("batchComplete",()=>toast("All queued inventory items were confirmed by the GC."));c.addEventListener("batchDeleteComplete",()=>toast("All selected items were deleted and confirmed by the GC."));c.addEventListener("deleted",e=>toast("Item "+e.detail.lowId+" deleted and confirmed."));c.addEventListener("uncertain",e=>toast("GC did not confirm the "+e.detail.action+" request. Reconnect and inspect inventory before retrying."));c.addEventListener("error",e=>alert(e.detail));c.connect();showPage("connection")}
render();loadDefaultIconManifest();
